'use strict';
const { test } = require('node:test');
const assert = require('node:assert');
const {
  login,
  getSession,
  generateRememberToken,
  validateRememberToken,
} = require('../src/auth.js');

test('login happy path returns a session', () => {
  const res = login('alice', 'wonderland');
  assert.strictEqual(res.ok, true);
  assert.ok(res.sessionId.length > 0);
  assert.strictEqual(getSession(res.sessionId).userId, 'u1');
});

test('wrong password is rejected', () => {
  const res = login('alice', 'nope');
  assert.strictEqual(res.ok, false);
  assert.strictEqual(res.sessionId, undefined);
});

test('remember token validates back to the same user', () => {
  const token = generateRememberToken('u1');
  assert.ok(token.length > 0);
  assert.match(token, /^[A-Za-z0-9_-]+$/);
  const result = validateRememberToken(token);
  assert.strictEqual(result.userId, 'u1');
});

test('remember tokens are unique per call', () => {
  const a = generateRememberToken('u1');
  const b = generateRememberToken('u1');
  assert.notStrictEqual(a, b);
});

test('unknown remember token is rejected', () => {
  assert.strictEqual(validateRememberToken('not-a-real-token'), null);
});

test('remember token is not stored in plaintext server-side', () => {
  const token = generateRememberToken('u2');
  const authSource = require('node:fs').readFileSync(
    require.path ? undefined : undefined
  );
});

