  assert.strictEqual(validateRememberToken(undefined), null);
  assert.strictEqual(validateRememberToken(null), null);
  assert.strictEqual(validateRememberToken(12345), null);
});

test('expired remember token is rejected', (t) => {
  t.mock.timers.enable({ apis: ['Date'] });
  const token = generateRememberToken('u1');
  t.mock.timers.tick(31 * 24 * 60 * 60 * 1000);
  assert.strictEqual(validateRememberToken(token), null);
});

